    # Let's use a different approach:
    # For a fixed n, we check if there's a safe set.
    # We can start with all distributions of n and keep only those that are safe.

    def get_distributions(m, n):
        def partitions(n, k):
            if k == 1:
                yield (n,)
                return
            for i in range(1, n - k + 2):
                for p in partitions(n - i, k - 1):
                    yield (i,) + p
        return list(partitions(n, m))

    for n in range(1, 100):
