                        for i in range(k, m):
                            nx[i] -= s
                        if all(val > 0 for val in nx):
                            possible_s.append(tuple(nx))

                    if not any(s_state in current_safe for s_state in possible_s):
                        all_k_ok = False
                        break
                if all_k_ok:
